def test_roc_auc_score_partial():
    # Integrate the simple ROC curve by hand, then apply McClish's correction.
    y_true = [0, 0, 1, 1]
    y_score = [0.1, 0.4, 0.35, 0.8]
    for max_fpr, expected in [(0.25, 5. / 7), (0.5, 2. / 3),
                              (0.75, 11. / 15)]:
        assert_almost_equal(roc_auc_score(y_true, y_score, max_fpr=max_fpr),
                            expected)

    # A tied positive and negative produce a sloping segment: the endpoint
    # at FPR=0.25 has TPR=0.75, giving a partial area of 0.15625.
    assert_almost_equal(roc_auc_score(y_true, [0.1, 0.4, 0.4, 0.8],
                                      max_fpr=0.25), 11. / 14)


def test_roc_auc_score_partial_standardization():
    y_true = [0, 0, 1, 1]
    for max_fpr in [0.01, 0.1, 0.5, 1.0]:
        assert_almost_equal(roc_auc_score(y_true, y_true, max_fpr=max_fpr), 1)
        assert_almost_equal(roc_auc_score(y_true, [0.5] * 4,
                                          max_fpr=max_fpr), 0.5)


def test_roc_auc_score_partial_invalid_max_fpr():
    for max_fpr in [-1, 0, 1.01, np.inf, np.nan]:
        assert_raise_message(ValueError, 'max_fpr', roc_auc_score,
                             [0, 1], [0, 1], max_fpr=max_fpr)


